export function getFlagSvg(code: string): string | undefined {
  if (SVG_FLAGS[code]) return SVG_FLAGS[code];
  const base = code.split('-')[0].toLowerCase();
  return SVG_FLAGS[base] || SVG_FLAGS['en'];
}
